<script setup lang="ts">
import{computed,onBeforeUnmount,onMounted,ref}from'vue';import{useRouter}from'vue-router';import{session}from'../api';import{enterpriseApi}from'../services/enterprise';import MetricCard from'../components/MetricCard.vue';import StatusPill from'../components/StatusPill.vue'
const router=useRouter(),devices=ref<any[]>([]),audit=ref<any[]>([]),loading=ref(true),error=ref(''),updated=ref(''),timer=ref<number>(),connected=ref(false)
const roleTitle=computed(()=>session.role==='owner'?'企业经营与技术准备度':session.role==='manager'?'设备健康与配置完成度':session.role==='operator'?'实时状态与异常处置':'企业运行状态只读视图')
const metrics=computed(()=>({total:devices.value.length,online:devices.value.filter(x=>x.online_state==='online').length,ready:devices.value.filter(x=>x.online_state==='online'&&x.collector_state==='healthy'&&x.studio_state==='running').length,blocked:devices.value.filter(x=>x.abnormal_reasons?.some((r:any)=>['DEVICE_OFFLINE','COLLECTOR_UNHEALTHY'].includes(r.code))).length,network:devices.value.filter(x=>x.abnormal_reasons?.some((r:any)=>r.code.includes('NETWORK')||r.code.includes('UPLOAD'))).length,studio:devices.value.filter(x=>x.studio_state==='running').length,issues:devices.value.reduce((sum,x)=>sum+(x.abnormal_reasons?.length||0),0)}))
const onlineRate=computed(()=>metrics.value.total?Math.round(metrics.value.online/metrics.value.total*100):0),configuration=computed(()=>{const b=session.bootstrap;if(!b)return 0;const checks=[metrics.value.total>0,(b.usage?.rooms||0)>0,(b.usage?.members||0)>0,b.organization?.onboarding?.completed];return Math.round(checks.filter(Boolean).length/checks.length*100)}),attention=computed(()=>devices.value.filter(x=>x.abnormal_reasons?.length).slice(0,8))
async function load(){loading.value=true;error.value='';try{const[deviceData,auditData]=await Promise.all([enterpriseApi.devices(new URLSearchParams({limit:'200',sort:'abnormal'})),enterpriseApi.audit(8)]);devices.value=deviceData.items||[];audit.value=auditData.items||[];connected.value=true;updated.value=new Date().toLocaleTimeString()}catch(e:any){connected.value=false;error.value=`${e.message}${e.requestId?`（请求编号 ${e.requestId}）`:''}`}finally{loading.value=false}}
onMounted(async()=>{await load();timer.value=window.setInterval(()=>{if(!document.hidden)load()},15000)});onBeforeUnmount(()=>{if(timer.value)clearInterval(timer.value)})
</script>
<template><div class="page-stack"><section class="command-hero"><div><span class="eyebrow light">ENTERPRISE OVERVIEW</span><h2>{{roleTitle}}</h2><p>{{session.bootstrap?.organization?.name}} · {{session.bootstrap?.organization?.plan_code}} 套餐。先处理阻断，再关注网络与直播软件风险。</p></div><div class="readiness-ring"><strong>{{onlineRate}}%</strong><span>设备在线率</span></div></section><div class="live-strip"><span :class="['live-dot',{off:!connected}]"></span>{{connected?'实时状态正常 · 15 秒刷新':'实时状态连接异常'}}<small>更新于 {{updated||'-'}}</small></div><div v-if="error" class="panel state-inline error"><b>工作台部分数据暂时不可用</b><span>{{error}}</span><button @click="load">立即重试</button></div><template v-if="loading&&!devices.length"><section class="metrics-grid"><i v-for="n in 6" class="skeleton metric-card"></i></section><div class="panel skeleton detail-skeleton"></div></template><template v-else><section class="metrics-grid"><MetricCard label="在线设备" :value="`${metrics.online}/${metrics.total}`" tone="blue"/><MetricCard label="可以准备开播" :value="metrics.ready" tone="green"/><MetricCard label="需要立即处理" :value="metrics.blocked" tone="red"/><MetricCard label="网络风险" :value="metrics.network" tone="amber"/><MetricCard label="LIVE Studio运行" :value="metrics.studio" tone="violet"/><MetricCard label="异常提示" :value="metrics.issues" tone="red"/></section><section class="dashboard-split"><article class="panel"><header class="panel-head"><div><h3>需要立即处理</h3><p>按设备异常优先级展示，点击进入完整设备详情。</p></div><button @click="router.push({name:'enterprise-devices'})">全部设备</button></header><div v-if="!attention.length" class="empty-state success-empty"><b>当前没有实时异常</b><p>仍建议在每次开播前执行完整环境检测。</p></div><div v-else class="attention-list"><button v-for="x in attention" @click="router.push({name:'enterprise-device-detail',params:{deviceId:x.device_id}})"><span :class="['attention-dot',x.online_state]"></span><div><b>{{x.display_name}}</b><small>{{x.abnormal_reasons[0].message}}<template v-if="x.abnormal_reasons.length>1"> · 另有 {{x.abnormal_reasons.length-1}} 项</template></small></div><StatusPill :value="x.online_state"/></button></div></article><article class="panel"><header class="panel-head"><div><h3>企业配置完成度</h3><p>依据设备、直播间、成员和开通向导状态计算。</p></div><strong class="completion-value">{{configuration}}%</strong></header><div class="completion-track"><i :style="{width:`${configuration}%`}"></i></div><div class="check-grid"><span :class="{done:metrics.total}">设备接入</span><span :class="{done:(session.bootstrap?.usage?.rooms||0)>0}">直播间</span><span :class="{done:(session.bootstrap?.usage?.members||0)>0}">企业成员</span><span :class="{done:session.bootstrap?.organization?.onboarding?.completed}">开通向导</span></div><div class="version-summary"><span>客户端版本</span><b>{{[...new Set(devices.map(x=>x.agent_version).filter(Boolean))].join(' / ')||'暂无设备版本'}}</b></div></article></section><section class="dashboard-split"><article class="panel"><header class="panel-head"><div><h3>最近操作</h3><p>敏感变更均来自企业审计记录。</p></div></header><div v-if="!audit.length" class="empty-state">暂无企业操作记录。</div><div v-else class="timeline"><article v-for="x in audit"><i></i><div><b>{{x.action}}</b><p>{{x.actor}} · {{x.target_type}}</p></div><small>{{x.created_at?.replace('T',' ').slice(0,16)}}</small></article></div></article><article class="panel future-module"><span class="eyebrow">LIVE DATA BOUNDARY</span><h3>直播数据模块尚未启用</h3><p>当前 Phase 1.5 只展示 LIVE Studio 进程和设备准备状态，不抓取 TikTok 真实直播指标，也不读取账号密码、Cookie 或浏览器会话。</p><span class="source-chip default">将在 Phase 2 单独评估接入</span></article></section></template></div></template>
